1	export const INVESTMENT_TIERS = [
2	  { dollars: 5000, cents: 500_000, envKey: 'EASY_API_PRICE_ID_5K' },
3	  { dollars: 10000, cents: 1_000_000, envKey: 'EASY_API_PRICE_ID_10K' },
4	  { dollars: 25000, cents: 2_500_000, envKey: 'EASY_API_PRICE_ID_25K' },
5	  { dollars: 50000, cents: 5_000_000, envKey: 'EASY_API_PRICE_ID_50K' },
6	  { dollars: 100000, cents: 10_000_000, envKey: 'EASY_API_PRICE_ID_100K' },
7	  { dollars: 250000, cents: 25_000_000, envKey: 'EASY_API_PRICE_ID_250K' },
8	] as const;
9	
10	export type InvestmentTier = (typeof INVESTMENT_TIERS)[number];
11	export type TierDollars = InvestmentTier['dollars'];
12	
13	export const isTierDollars = (value: number): value is TierDollars =>
14	  INVESTMENT_TIERS.some((t) => t.dollars === value);
15	
16	export const getTierByDollars = (dollars: TierDollars): InvestmentTier => {
17	  const tier = INVESTMENT_TIERS.find((t) => t.dollars === dollars);
18	  if (!tier) throw new Error(`Unknown investment tier: ${dollars}`);
19	  return tier;
20	};
21	
22	export const getPriceIdForTier = (dollars: TierDollars): string => {
23	  const tier = getTierByDollars(dollars);
24	  const id = process.env[tier.envKey];
25	  if (!id) {
26	    throw new Error(
27	      `Missing ${tier.envKey} env var. Run \`yarn setup:easy-api\` to bootstrap Easy API products.`,
28	    );
29	  }
30	  return id;
31	};
