29	  const fetchReturns = async () => {
30	    try {
31	      setLoading(true);
32	      const transactionsRef = collection(db, 'transactions');
33	      const q = query(
34	        transactionsRef,
35	        where('projectId', '==', project.id),
36	        where('type', '==', 'return'),
37	      );
38	
39	      const querySnapshot = await getDocs(q);
40	      const fetchedReturns: Transaction[] = [];
41	
42	      querySnapshot.forEach((doc) => {
43	        fetchedReturns.push(doc.data() as Transaction);
44	      });
45	
46	      // Sort by date descending
47	      fetchedReturns.sort((a, b) => b.date - a.date);
48	
49	      setReturns(fetchedReturns);
50	    } catch (error) {
51	      console.error('Error fetching returns:', error);
52	    } finally {
53	      setLoading(false);
54	    }
55	  };
56	
57	  useEffect(() => {
58	    fetchReturns();
