99	const parseBody = async (response: Response): Promise<unknown> => {
100	  if (
101	    response.status === 204 ||
102	    response.headers.get('content-length') === '0'
103	  ) {
104	    return null;
105	  }
106	
107	  const contentType = response.headers.get('content-type') ?? '';
108	  if (contentType.includes('application/json')) {
