import { INVESTMENT_TIERS } from 'const/investment-tiers';
import { createProduct, createProductPrice } from 'lib/easy-api/products';
import { getProjectById, updateProject } from 'lib/firebase/server-actions';
import { NextResponse } from 'next/server';

export async function POST(request: Request) {
  let projectId: string;

  try {
    const body = await request.json();
    projectId = body.projectId;
  } catch {
    return NextResponse.json({ error: 'Invalid request body.' }, { status: 400 });
  }

  if (!projectId) {
    return NextResponse.json({ error: 'Missing projectId.' }, { status: 400 });
  }

  const project = await getProjectById(projectId);

  if (!project) {
    return NextResponse.json({ error: 'Project not found.' }, { status: 404 });
  }

  const productResult = await createProduct({
    name: project.name,
    description: project.description,
    active: true,
    metadata: { projectId, app: 'beni-capital' },
    image_url: project.heroImage || '',
  });

  if (!productResult.ok) {
    return NextResponse.json({ error: productResult.error }, { status: productResult.status });
  }

  const productId = productResult.data.id;
  const priceIds: Record<string, string> = {};

  for (const tier of INVESTMENT_TIERS) {
    const priceResult = await createProductPrice({
      product_id: productId,
      currency: 'USD',
      unit_amount: tier.cents,
      recurring: false,
      active: true,
      tax_behavior: 'exclusive',
      description: `${project.name} — $${tier.dollars.toLocaleString()} investment tier`,
      pricing_model: 'per_unit',
    });

    if (!priceResult.ok) {
      return NextResponse.json({ error: priceResult.error }, { status: priceResult.status });
    }

    priceIds[String(tier.dollars)] = priceResult.data.id;
  }

  await updateProject(projectId, {
    easyApiProductId: productId,
    easyApiPriceIds: priceIds,
  });

  const updatedProject = await getProjectById(projectId);

  return NextResponse.json({ project: updatedProject });
}

'use client';

import { INVESTMENT_TIERS } from 'const/investment-tiers';
import { Button } from '@modules/shared/button';
import { CheckCircle2, Circle } from 'lucide-react';
import { toast } from 'sonner';
import { FC, useState } from 'react';

interface Props {
  project: Project & { id: string };
}

export const EasyApiSetup: FC<Props> = ({ project }) => {
  const [currentProject, setCurrentProject] = useState(project);
  const [loading, setLoading] = useState(false);

  const isFullyConfigured =
    !!currentProject.easyApiProductId &&
    INVESTMENT_TIERS.every((t) => !!currentProject.easyApiPriceIds?.[String(t.dollars)]);

  const handleSetup = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/easy-api/setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectId: currentProject.id }),
      });

      const json = await res.json();

      if (!res.ok) {
        toast.error(json?.error?.message ?? 'Failed to configure Easy API.');
        return;
      }

      setCurrentProject(json.project);
      toast.success('Easy API configured successfully.');
    } catch {
      toast.error('An unexpected error occurred.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-[16px] shadow-lg p-24">
      <div className="flex items-start justify-between mb-16">
        <div>
          <h2 className="text-[clamp(20px,22px)] leading-[clamp(24px,28px)] font-semibold">
            Easy API Payments
          </h2>
          <p className="text-sm text-gray-500 mt-4">
            Product and price configuration for this project&apos;s investment tiers.
          </p>
        </div>
        <Button
          onClick={handleSetup}
          disabled={loading}
          variant={isFullyConfigured ? 'secondary' : 'default'}
          size="small">
          {isFullyConfigured ? 'Re-configure' : 'Setup Easy API'}
        </Button>
      </div>

      {currentProject.easyApiProductId && (
        <div className="bg-gray-50 rounded-lg p-12 mb-16">
          <p className="text-xs text-gray-500 mb-4">Product ID</p>
          <p className="font-mono text-sm">{currentProject.easyApiProductId}</p>
        </div>
      )}

      <div className="grid grid-cols-3 gap-8 mt-16">
        {INVESTMENT_TIERS.map((tier) => {
          const priceId = currentProject.easyApiPriceIds?.[String(tier.dollars)];
          const configured = !!priceId;

          return (
            <div key={tier.dollars} className="bg-gray-50 rounded-lg p-12">
              <div className="flex items-center justify-between mb-8">
                <p className="text-sm font-semibold">
                  ${tier.dollars.toLocaleString()}
                </p>
                {configured ? (
                  <CheckCircle2 className="h-4 w-4 text-green-500" />
                ) : (
                  <Circle className="h-4 w-4 text-gray-300" />
                )}
              </div>
              <p className="font-mono text-xs text-gray-500 truncate">
                {priceId ? `${priceId.slice(0, 8)}...` : '—'}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
};

